class ReviewerAvailabilityServiceTests(TestCase):
    def test_get_or_create_returns_same_row(self):
        user = _make_user()

        first = reviewer_availability_service.get_or_create_availability(user=user)
        second = reviewer_availability_service.get_or_create_availability(user=user)

        self.assertEqual(first.id, second.id)
        self.assertEqual(ReviewerAvailability.objects.filter(user=user).count(), 1)

    def test_is_available_defaults_true_when_no_row_exists(self):
        user = _make_user()

        self.assertTrue(reviewer_availability_service.is_reviewer_available(user=user))

    def test_is_available_false_when_marked_unavailable(self):
        user = _make_user()
        reviewer_availability_service.update_availability(user=user, is_available=False)

        self.assertFalse(reviewer_availability_service.is_reviewer_available(user=user))

    def test_setting_available_clears_reason_and_return_date(self):
        user = _make_user()
        reviewer_availability_service.update_availability(
            user=user,
            is_available=False,
            unavailability_reason=UnavailabilityReason.VACATION,
            return_date=timezone.localdate() + timedelta(days=3),
        )

        result = reviewer_availability_service.update_availability(
            user=user, is_available=True
        )

        self.assertEqual(result.unavailability_reason, "")
        self.assertIsNone(result.return_date)

    def test_auto_return_when_return_date_has_passed(self):
        user = _make_user()
        reviewer_availability_service.update_availability(
            user=user,
            is_available=False,
            return_date=timezone.localdate() - timedelta(days=1),
        )

        self.assertTrue(reviewer_availability_service.is_reviewer_available(user=user))

    def test_no_auto_return_when_disabled(self):
        user = _make_user()
        reviewer_availability_service.update_availability(
            user=user,
            is_available=False,
            return_date=timezone.localdate() - timedelta(days=1),
            auto_return_enabled=False,
        )

        self.assertFalse(reviewer_availability_service.is_reviewer_available(user=user))

    def test_require_reviewer_available_raises_when_unavailable(self):
        user = _make_user()
        reviewer_availability_service.update_availability(user=user, is_available=False)

        with self.assertRaises(ValidationError):
            reviewer_availability_service.require_reviewer_available(user=user)


class ReviewerAvailabilityApiTests(APITestCase):
    def test_requires_authentication(self):
        response = self.client.get("/api/v1/users/me/availability/")
        self.assertEqual(response.status_code, status.HTTP_401_UNAUTHORIZED)

    def test_get_lazily_creates_default_available(self):
        user = _make_user()
        self.client.force_authenticate(user)

        response = self.client.get("/api/v1/users/me/availability/")
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertTrue(response.data["is_available"])
        self.assertTrue(response.data["is_effectively_available"])

    def test_patch_set_unavailable_with_reason_and_return_date(self):
        user = _make_user()
        self.client.force_authenticate(user)

        response = self.client.patch(
            "/api/v1/users/me/availability/",
            {
                "is_available": False,
                "unavailability_reason": "VACATION",
                "return_date": str(timezone.localdate() + timedelta(days=5)),
            },
            format="json",
        )
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        self.assertFalse(response.data["is_available"])
        self.assertEqual(response.data["unavailability_reason"], "VACATION")

    def test_patch_empty_body_rejected(self):
        user = _make_user()
        self.client.force_authenticate(user)

        response = self.client.patch(
            "/api/v1/users/me/availability/", {}, format="json"
        )
        self.assertEqual(response.status_code, status.HTTP_400_BAD_REQUEST)

    def test_patch_logs_configuration_activity(self):
        user = _make_user()
        self.client.force_authenticate(user)

        self.client.patch(
            "/api/v1/users/me/availability/",
            {"is_available": False},
            format="json",
        )

        self.assertTrue(
            UserActivityLog.objects.filter(
                user=user, action=UserActivityActionEnums.AVAILABILITY_UPDATED
            ).exists()
        )


class UserActivityLogApiTests(APITestCase):
    def test_requires_authentication(self):
        response = self.client.get("/api/v1/users/me/activity-log/")
        self.assertEqual(response.status_code, status.HTTP_401_UNAUTHORIZED)

    def test_lists_only_own_entries(self):
        user = _make_user()
        other = _make_user()
        UserActivityLog.objects.create(
            user=user,
            actor_user=user,
            category="CONFIGURATION",
            action="PROFILE_UPDATED",
            summary="You updated your profile.",
            activity_datetime=timezone.now(),
        )
        UserActivityLog.objects.create(
            user=other,
            actor_user=other,
            category="CONFIGURATION",
            action="PROFILE_UPDATED",
            summary="Someone else's activity.",
            activity_datetime=timezone.now(),
        )
        self.client.force_authenticate(user)

        response = self.client.get("/api/v1/users/me/activity-log/")
        self.assertEqual(response.status_code, status.HTTP_200_OK)
        results = response.data["data"]["results"]
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0]["summary"], "You updated your profile.")

    def test_filter_by_category(self):
        user = _make_user()
        UserActivityLog.objects.create(
            user=user,
            actor_user=user,
            category="CONFIGURATION",
            action="PROFILE_UPDATED",
            summary="Config change.",
            activity_datetime=timezone.now(),
        )
        UserActivityLog.objects.create(
            user=user,
            actor_user=user,
            category="COURSE",
            action="COURSE_ASSIGNED",
            summary="Course assigned to you.",
            activity_datetime=timezone.now(),
        )
        self.client.force_authenticate(user)

        response = self.client.get(
            "/api/v1/users/me/activity-log/", {"category": "COURSE"}
        )
        results = response.data["data"]["results"]
        self.assertEqual(len(results), 1)
        self.assertEqual(results[0]["summary"], "Course assigned to you.")


class KYCServiceTests(TestCase):
    def test_is_verified_false_with_no_submission(self):
        user = _make_user()

        self.assertFalse(kyc_service.is_verified(user=user))

    def test_is_verified_true_when_latest_is_approved(self):
        user = _make_user()
        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
        )
        KYCVerification.objects.filter(user=user).update(status=KYCStatus.APPROVED)

        self.assertTrue(kyc_service.is_verified(user=user))

    def test_cannot_submit_while_a_pending_submission_exists(self):
        user = _make_user()
        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
        )

        with self.assertRaises(ValidationError):
            kyc_service.submit_verification(
                user=user,
                country_of_issue="NG",
                document_type="VOTERS_ID",
                id_number="67890",
            )

    def test_can_resubmit_after_rejection(self):
        user = _make_user()
        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
        )
        KYCVerification.objects.filter(user=user).update(status=KYCStatus.REJECTED)

        resubmission = kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="VOTERS_ID",
            id_number="67890",
        )

        self.assertEqual(resubmission.status, KYCStatus.PENDING)

    def test_require_verified_raises_when_not_verified(self):
        user = _make_user()

        with self.assertRaises(ValidationError):
            kyc_service.require_verified(user=user)

    def test_admin_who_opted_out_is_not_notified(self):
        subscribed_admin = _make_user(role=UserRole.ADMIN)
        opted_out_admin = _make_user(role=UserRole.ADMIN)
        notification_preference_service.update_preference(
            user=opted_out_admin, kyc_submission_alert=False
        )
        user = _make_user()

        kyc_service.submit_verification(
            user=user,
            country_of_issue="NG",
            document_type="NATIONAL_ID",
            id_number="12345",
        )

        self.assertTrue(
            Notification.objects.filter(
                receiver=subscribed_admin, title="New KYC verification request"
            ).exists()
        )
        self.assertFalse(
            Notification.objects.filter(
                receiver=opted_out_admin, title="New KYC verification request"
            ).exists()
        )


